// One search per reference per eBay country site.
// Add or remove sites here (EBAY_US, EBAY_GB, EBAY_DE, EBAY_FR, EBAY_IT, EBAY_AU, EBAY_CH, EBAY_HK ...)
const MARKETPLACES = ['EBAY_US', 'EBAY_GB', 'EBAY_DE', 'EBAY_CH', 'EBAY_HK'];

const searches = [];
for (const item of $input.all()) {
  for (const marketplace of MARKETPLACES) {
    searches.push({
      json: {
        brand: item.json.brand,
        reference: item.json.reference,
        query: `${item.json.brand} ${item.json.reference}`,
        marketplace,
      },
    });
  }
}
return searches;

// Keep only real, complete watches whose title contains the reference number.
const JUNK = /(box only|empty box|strap only|bracelet only|for parts|not working|repair|replica|homage|dial only|bezel only|papers only|manual only)/i;
const clean = (s) => String(s || '').toLowerCase().replace(/[^a-z0-9]/g, '');

// eBay condition text -> our condition names (see table condition_factors)
function mapCondition(text) {
  const t = String(text || '').toLowerCase();
  if (t.startsWith('new with')) return 'new';
  if (t.startsWith('new')) return 'unworn';
  if (t.includes('parts')) return 'fair';
  return 'good'; // "Pre-owned": we do not know more, so we assume "good"
}

const searches = $('Build searches').all();
const rows = [];

$input.all().forEach((item, i) => {
  const index = item.pairedItem?.item ?? i;
  const search = searches[index]?.json;
  if (!search || !item.json.itemSummaries) return; // error or no results

  for (const s of item.json.itemSummaries) {
    const title = s.title || '';
    if (JUNK.test(title)) continue;
    if (!clean(title).includes(clean(search.reference))) continue;
    if (!s.price?.value) continue;

    rows.push({
      json: {
        external_id: s.itemId,
        seller: s.seller?.username || null,
        brand: search.brand,
        reference: search.reference,
        title,
        condition: mapCondition(s.condition),
        price: Number(s.price.value),
        currency: s.price.currency,
        country: s.itemLocation?.country || null,
        url: s.itemWebUrl || null,
      },
    });
  }
});
return rows;

// When the database query finds nothing, n8n still passes one item: {"success": true}.
// Remove it so the next steps only run for real rows.
return $input.all()
  .map((item, index) => ({ json: item.json, pairedItem: { item: index } }))
  .filter(item => !(Object.keys(item.json).length === 1 && item.json.success === true));
